import { getPosts } from '@/lib/api';

export const revalidate = 3600;
export const tags = ['posts'];

async function fetchPosts() {
  'use cache';
  return await getPosts();
}

export default async function Home() {
  const posts = await fetchPosts();

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  );
}

